// V15.9.6 navigation boot guard: dashboard remains usable even if a later API call fails.
document.documentElement.classList.add('furkai-js-ready');
const $=id=>document.getElementById(id); let page='dashboard';
const MODELS=['Özel Filtre','10/50 Crossover','Golden Cross','52H Kırılım','Akıllı Para Proxy','Tavan Tarama','Ucuz Kalmış','Hacimlenen Dip','Momentum Bombası','Destek Kalkanı','Bollinger Sıkışma','Stoch RSI','MACD Kesişimi','Doji','Hammer','Supertrend','EMA Crossover','ADX Güçlü Trend','Morning Star','Engulfing','Değer + Momentum','Ichimoku Bulutu','Qullamaggie','Minervini Trend','Bulkowski Formasyon','RSI Trend Kırılımı','Pozitif Uyuşmazlık'];
async function go(p){
  page=p;
  window.__furkaiPage=p;
  const sections=[...document.querySelectorAll('.main > .section')];
  sections.forEach(x=>{
    const active=x.id===p;
    x.classList.toggle('active',active);
    x.setAttribute('aria-hidden',active?'false':'true');
    // Inline !important is intentional: it prevents stale/duplicated CSS from ever
    // leaving another page visible underneath the selected page.
    x.style.setProperty('display',active?'block':'none','important');
    x.style.setProperty('visibility',active?'visible':'hidden','important');
  });
  const main=document.querySelector('.main');
  if(main) main.scrollTop=0;
  window.scrollTo({top:0,left:0,behavior:'auto'});
  document.querySelectorAll('.nav button[data-page], .mobile-bar button[data-page]').forEach(x=>{const active=x.dataset.page===p;x.classList.toggle('active',active);x.setAttribute('aria-current',active?'page':'false')});
  try{
    if(p==='dashboard'){const now=Date.now();if(now-(window._dashLoadedAt||0)>15000) loadDashboard().catch(()=>{})}
    else if(p==='scanner'){if($('modelGrid')&&!$('modelGrid').children.length) renderModels()}
    else if(p==='signals'){await loadSignals()}
    else if(p==='portfolio'){await loadPortfolio();if($('portIntel'))$('portIntel').innerHTML='<div class="empty">Portföy Intelligence için <b>Yenile</b>ye bas. Ağır analiz ilk açılışta otomatik çalıştırılmaz.</div>'}
    else if(p==='dividends'){await loadDividends()}
    else if(p==='settings'){await loadSettings();await loadDataStatus()}
  }catch(e){const target=p==='portfolio'?'portTable':p==='signals'?'signalTable':p==='dividends'?'divTable':p==='settings'?'settingsStatus':null;if(target&&$(target))$(target).innerHTML='<div class="note bad">'+esc(e.message||'Bölüm yüklenemedi.')+'</div>'}
}
function authHeader(){const a=sessionStorage.getItem('furkai_auth');return a?{'Authorization':'Bearer '+a}:{};}
function authMode(){return sessionStorage.getItem('furkai_auth_mode')||'login'}
function toggleRegister(){const reg=authMode()!=='register';sessionStorage.setItem('furkai_auth_mode',reg?'register':'login');$('authTitle').textContent=reg?'FurkAI BIST Kayıt':'FurkAI BIST Giriş';$('authSubtitle').textContent=reg?'Yeni hesabını oluştur. İlk kaydı oluşturan hesap mevcut yerel portföyü devralır.':'Hesabınla giriş yap.';$('registerPass2').style.display=reg?'block':'none';$('registerPass2').value='';$('authSubmit').textContent=reg?'Kayıt Ol':'Giriş Yap';$('authSubmit').onclick=reg?registerUser:login;$('authToggle').textContent=reg?'Giriş ekranına dön':'Yeni hesap oluştur';$('loginErr').textContent=''}
async function login(){const u=$('loginUser').value.trim(),p=$('loginPass').value,err=$('loginErr');err.textContent='';if(!u||!p){err.textContent='Kullanıcı adı ve şifre zorunlu.';return}try{const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,password:p})});const d=await r.json();if(!r.ok){err.textContent=d.detail||d.error||'Kullanıcı adı veya şifre hatalı.';return}sessionStorage.setItem('furkai_auth',d.token);sessionStorage.setItem('furkai_auth_mode','login');location.reload()}catch(e){err.textContent='Sunucuya bağlanılamadı.'}}
async function registerUser(){const u=$('loginUser').value.trim(),p=$('loginPass').value,p2=$('registerPass2').value,err=$('loginErr');err.textContent='';if(!u||!p||!p2){err.textContent='Tüm alanları doldur.';return}if(p!==p2){err.textContent='Şifreler eşleşmiyor.';return}try{const r=await fetch('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,password:p})});const d=await r.json();if(!r.ok){err.textContent=d.detail||d.error||'Kayıt oluşturulamadı.';return}sessionStorage.setItem('furkai_auth',d.token);sessionStorage.setItem('furkai_auth_mode','login');location.reload()}catch(e){err.textContent='Sunucuya bağlanılamadı.'}}
function logout(){const token=sessionStorage.getItem('furkai_auth');if(token)fetch('/api/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+token}}).catch(()=>{});sessionStorage.removeItem('furkai_auth');sessionStorage.removeItem('furkai_auth_mode');location.reload()}
function showToast(message,type='info'){const host=$('toastStack');if(!host)return;const el=document.createElement('div');el.className='toast '+(type==='bad'?'bad':'');el.textContent=message;host.appendChild(el);setTimeout(()=>el.remove(),4200)}async function get(u,o={}){o.headers={...(o.headers||{}),...authHeader()};const ctrl=new AbortController();const timer=setTimeout(()=>ctrl.abort(),20000);o.signal=o.signal||ctrl.signal;try{const r=await fetch(u,o);if(r.status===401){$('login').style.display='flex';throw Error('Giriş gerekli');}const d=await r.json();if(!d.ok&&d.error)throw Error(d.error);return d}catch(e){if(e.name==='AbortError'){showToast('İstek 20 saniyede yanıt vermedi.','bad');throw Error('İstek zaman aşımına uğradı (20 sn).')}showToast(e.message||'İstek başarısız.','bad');throw e}finally{clearTimeout(timer)}}
window.addEventListener('load',async()=>{const token=sessionStorage.getItem('furkai_auth');if(!token){$('login').style.display='flex';if(authMode()==='register')toggleRegister();return}try{const r=await fetch('/api/auth/me',{headers:{Authorization:'Bearer '+token}});if(!r.ok)throw Error('session');const md=await r.json();window.currentUser=md.user||null;$('login').style.display='none'}catch(_){sessionStorage.removeItem('furkai_auth');$('login').style.display='flex'}});
const fmt=n=>n==null?'—':Number(n).toLocaleString('tr-TR',{maximumFractionDigits:2});
function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;')}

const MODEL_CATS={trend:['10/50 Crossover','Golden Cross','EMA Crossover','ADX Güçlü Trend','Supertrend','Ichimoku Bulutu','Minervini Trend','52H Kırılım'],momentum:['Momentum Bombası','Stoch RSI','MACD Kesişimi','RSI Trend Kırılımı','Pozitif Uyuşmazlık','Qullamaggie'],breakout:['52H Kırılım','Bollinger Sıkışma','Tavan Tarama','Hacimlenen Dip'],pattern:['Doji','Hammer','Morning Star','Engulfing','Bulkowski Formasyon'],value:['Ucuz Kalmış','Değer + Momentum','Destek Kalkanı'],flow:['Akıllı Para Proxy']};
function modelCategory(m){for(const [k,arr] of Object.entries(MODEL_CATS))if(arr.includes(m))return k;return 'trend'}
function renderModels(){const g=$('modelGrid');const q=($('modelSearch')?.value||'').trim().toLowerCase();const cat=window.modelCat||'all';g.innerHTML=MODELS.map(m=>{const show=(!q||m.toLowerCase().includes(q))&&(cat==='all'||modelCategory(m)===cat);return `<label class="model" data-model="${esc(m)}" data-cat="${esc(modelCategory(m))}" style="${show?'':'display:none'}"><input type="checkbox" value="${esc(m)}" onchange="modelChanged()"><span>${esc(m)}</span></label>`}).join('');modelChanged()}
function filterModels(){renderModels()}
function filterModelCategory(cat,btn){window.modelCat=cat;document.querySelectorAll('.model-cats button').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');renderModels()}
function selectAllModels(){document.querySelectorAll('#modelGrid .model:not([style*=\"display: none\"]) input').forEach(x=>x.checked=true);modelChanged()}
function clearModels(){document.querySelectorAll('#modelGrid input').forEach(x=>x.checked=false);modelChanged()}
function clearScanner(){clearModels();lastScanRows=[];$('scanTable').innerHTML='<div class="scan-empty muted">Filtreler temizlendi. Tarama başlatmaya hazır.</div>';$('scanStatus').textContent='Henüz tarama yapılmadı.';$('scanAiPanel').style.display='none';$('scanAiPanel').innerHTML=''}
function setScanPreset(p){clearModels();const sets={trend:['10/50 Crossover','Golden Cross','EMA Crossover','Supertrend','ADX Güçlü Trend','Minervini Trend'],momentum:['Momentum Bombası','Stoch RSI','MACD Kesişimi','RSI Trend Kırılımı','Pozitif Uyuşmazlık'],breakout:['52H Kırılım','Bollinger Sıkışma','Tavan Tarama','Hacimlenen Dip'],value:['Ucuz Kalmış','Değer + Momentum','Destek Kalkanı'],risk:['10/50 Crossover','Golden Cross','ADX Güçlü Trend','Supertrend','Destek Kalkanı']};(sets[p]||[]).forEach(m=>{const el=[...document.querySelectorAll('#modelGrid input')].find(x=>x.value===m);if(el)el.checked=true});$('scanMode').value=p==='risk'?'AND':'OR';$('scanMin').value=p==='risk'?70:p==='momentum'?65:60;updateMinModelsVisibility();modelChanged()}
function updateMinModelsVisibility(){const or=$('scanMode').value==='OR';$('scanMinModels').disabled=!or;if(!or)$('scanMinModels').value=1;const n=Number($('scanMinModels').value)||1;$('scanSelectionText').textContent=or?'OR: en az '+n+' model eşleşmeli.':'AND: seçilen modellerin tamamı eşleşmeli.'}

function selectedModels(){return [...document.querySelectorAll('#modelGrid input:checked')].map(x=>x.value)}
function modelChanged(){const boxes=[...document.querySelectorAll('#modelGrid input')],sel=boxes.filter(x=>x.checked);if(sel.length>27){sel.at(-1).checked=false;return}$('modelCount').textContent=sel.length+' / 27';updateMinModelsVisibility();$('scanSelectionText').textContent=sel.length?($('scanMode').value==='OR'?'OR: en az '+Math.min(Number($('scanMinModels').value)||1,sel.length)+' model eşleşmeli.':'AND: '+sel.length+' seçilen modelin tamamı eşleşmeli.'):'Model seçmeden FurkAI Score taraması da yapabilirsin.'}
function modelTags(x){return (x.selected_models||x.active_models||[]).slice(0,6).map(m=>`<span class="tag">${esc(m)}</span>`).join('')}
let lastScanRows=[];function table(rows){lastScanRows=Array.isArray(rows)?rows:[];if(!lastScanRows.length)return `<div class="scan-empty muted">Bu filtrelerle aday bulunamadı. <br><small>Min Score'u düşür veya model mantığını OR yap.</small></div>`;return `<table class="table"><thead><tr><th>Hisse</th><th>Fiyat</th><th>FurkAI</th><th>Karar</th><th>RSI</th><th>Hacim</th><th>Eşleşen Modeller</th><th>Aksiyon</th></tr></thead><tbody>${lastScanRows.map(x=>{const sym=String(x.symbol||'').replace('.IS','');const sig=x.signal||'BEKLE';return `<tr class="scan-row" onclick="openStock('${encodeURIComponent(sym)}')"><td><b>${esc(sym)}</b></td><td>${fmt(x.price)} ₺</td><td><span class="pill score">${fmt(x.score)}/100</span></td><td class="signal-chip ${sig==='AL'?'good':sig==='BEKLE'?'warn':'bad'}">${esc(sig)}</td><td>${fmt(x.rsi)}</td><td>${fmt(x.volume_ratio)}x</td><td>${modelTags(x)}</td><td onclick="event.stopPropagation()"><div class="scan-result-actions"><button class="ghost" onclick="openStock('${encodeURIComponent(sym)}')">Analiz</button><button class="primary" onclick="aiFromScan('${encodeURIComponent(sym)}')">AI</button></div></td></tr>`}).join('')}</tbody></table>`}
function sortScanResults(){const k=$('scanSort').value;if(k==='symbol')lastScanRows.sort((a,b)=>String(a.symbol).localeCompare(String(b.symbol)));else if(k==='volume')lastScanRows.sort((a,b)=>(b.volume_ratio||0)-(a.volume_ratio||0));else if(k==='rsi')lastScanRows.sort((a,b)=>(a.rsi||0)-(b.rsi||0));else lastScanRows.sort((a,b)=>(b.score||0)-(a.score||0));$('scanTable').innerHTML=table(lastScanRows)}

async function runScan(){const st=$('scanStatus'),models=selectedModels(),btn=document.querySelector('#scanner .scan-controls .primary');if(btn?.disabled)return;btn.disabled=true;btn.textContent='⏳ Taranıyor…';st.innerHTML='<span class="scan-loading"><i class="spinner"></i> Piyasa taranıyor… '+models.length+' model değerlendiriliyor.</span>';$('scanTable').innerHTML='';$('scanAiPanel').style.display='none';let u='/api/scan?range='+$('scanRange').value+'&min='+$('scanMin').value+'&limit='+$('scanLimit').value+'&models='+encodeURIComponent(models.join('|'))+'&mode='+$('scanMode').value;if($('scanMode').value==='OR')u+='&min_models='+encodeURIComponent($('scanMinModels').value);try{const d=await get(u);localStorage.setItem('furkai_last_scan',JSON.stringify({ts:Date.now(),results:d.results||[],meta:{scanned:d.scanned||0,errors:d.errors?.length||0,mode:d.mode||'FurkAI skor'}}));st.textContent=`${d.scanned||0} hisse tarandı · ${d.results?.length||0} aday · ${d.errors?.length||0} veri hatası · ${d.mode||'FurkAI skor'} · ${d.cached?'önbellekten':'yeni veri'}`;$('scanTable').innerHTML=table(d.results);if(d.results?.length){const top=d.results[0];$('scanAiPanel').style.display='block';$('scanAiPanel').innerHTML=`<div class="ai-panel-head"><div><div class="ai-source">TARAMA KARAR ÖZETİ</div><h3>En güçlü aday: ${esc(String(top.symbol).replace('.IS',''))} · ${fmt(top.score)}/100</h3></div><button class="ghost" onclick="aiFromScan('${encodeURIComponent(String(top.symbol).replace('.IS',''))}')">🤖 Bu hisseyi AI ile yorumla</button></div><div class="ai-panel-body"><div class="ai-placeholder">Önce teknik sonucu gör. AI yorumu bu ekranın içinde açılır; ayrı kayan pencere oluşturmaz.</div></div>`}}catch(e){st.textContent='Hata: '+e.message;$('scanTable').innerHTML='<div class="note bad">'+esc(e.message)+'</div>'}finally{if(btn){btn.disabled=false;btn.textContent='🔎 Taramayı Başlat'}}}
async function loadSignals(){try{const sym=$('sigSym').value.trim().toUpperCase();const u='/api/signals?limit='+$('sigLimit').value+(sym?'&symbol='+encodeURIComponent(sym):'');const d=await get(u);const arr=Array.isArray(d.signals)?d.signals:[];if($('sigBuyCount'))$('sigBuyCount').textContent=arr.filter(x=>String(x.signal||x.decision||'').toUpperCase()==='AL').length;if($('sigSellCount'))$('sigSellCount').textContent=arr.filter(x=>String(x.signal||x.decision||'').toUpperCase()==='SAT').length;if($('sigHoldCount'))$('sigHoldCount').textContent=arr.filter(x=>{const v=String(x.signal||x.decision||'').toUpperCase();return !['AL','SAT'].includes(v)}).length;$('signalTable').innerHTML=arr.length?'<table class="table"><thead><tr><th>Tarih</th><th>Hisse</th><th>Sinyal</th><th>Tarama</th><th>Sinyal Fiyatı</th><th>Güncel</th><th>Getiri</th><th>1G</th><th>5G</th><th>20G</th><th>Skor</th></tr></thead><tbody>'+arr.map(x=>{const sig=String(x.signal||x.decision||'BEKLE').toUpperCase();return `<tr><td>${esc(x.date)}</td><td><b>${esc(x.symbol)}</b></td><td class="${sig==='AL'?'good':sig==='SAT'?'bad':'warn'}"><b>${esc(sig)}</b></td><td>${esc(x.models)}</td><td>${fmt(x.entry)}</td><td>${fmt(x.current)}</td><td class="${x.return_pct>=0?'good':'bad'}">${fmt(x.return_pct)}%</td><td>${fmt(x.ret_1d)}%</td><td>${fmt(x.ret_5d)}%</td><td>${fmt(x.ret_20d)}%</td><td>${fmt(x.score)}/100</td></tr>`}).join('')+'</tbody></table>':'<div class="empty">Henüz kayıtlı sinyal yok. Tarama çalıştırınca başarılı adaylar burada tutulur.</div>'}catch(e){$('signalTable').innerHTML='<div class="note">'+esc(e.message)+'</div>'}}
async function analyzeStock(){try{const sym=$('sym').value.trim().toUpperCase();const range=$('analysisRange').value;const d=(await get('/api/analyze?symbol='+encodeURIComponent(sym)+'&range='+range)).data;const hist=(await get('/api/history?symbol='+encodeURIComponent(sym)+'&range='+range+'&interval=1d')).data;window.currentAnalysis=d;const checks=Object.entries(d.checks||{}).map(([k,v])=>`<div class="check"><span>${esc(k)}</span><b class="${v?'good':'muted'}">${v?'✓':'—'}</b></div>`).join('');const models=Object.entries(d.models||{}).filter(([,v])=>v).map(([k])=>`<span class="tag">${esc(k)}</span>`).join('');const scoreMax={Trend:15,'Uzun Vade Trend':10,'Golden Cross':10,RSI:10,'Hacim/Akış':15,Breakout:10,Momentum:10,MACD:10,ADX:10};const bd=Object.entries(d.score_breakdown||{}).map(([k,v])=>{const max=scoreMax[k]||10;return `<div style="margin:10px 0"><div style="display:flex;justify-content:space-between"><span>${esc(k)}</span><b>${fmt(v)} / ${max} puan</b></div><div class="bar"><i style="width:${Math.min(100,(Number(v)/max)*100)}%"></i></div></div>`}).join('');const clean=String(d.symbol||sym).replace('.IS','');$('analysisOut').innerHTML=`<div class="hero"><div class="stockhead"><div><div class="mini-label">${esc(clean)} · TEKNİK ANALİZ</div><div class="big">${fmt(d.price)} ₺</div><div class="muted">Trend: <b>${esc(d.trend)}</b> · Hacim ${fmt(d.volume_ratio)}x · Momentum ${fmt(d.momentum)}%</div></div><div><span class="pill">${esc(d.signal)} · ${fmt(d.score)}/100</span></div></div></div><div class="card" style="margin-top:14px"><div class="charttools"><button onclick="setChartInterval('15m')" id="tf15m">15M</button><button onclick="setChartInterval('1h')" id="tf1h">1H</button><button onclick="setChartInterval('4h')" id="tf4h">4H</button><button onclick="setChartInterval('1d')" id="tf1d" class="on">1D</button><button onclick="setChartInterval('1w')" id="tf1w">1W</button><button onclick="setChartInterval('1mo')" id="tf1mo">1MO</button><button id="ema20Btn" class="on" onclick="toggleChart('ema20')">EMA20</button><button id="ema50Btn" class="on" onclick="toggleChart('ema50')">EMA50</button><button id="ema200Btn" onclick="toggleChart('ema200')">EMA200</button><button id="bbBtn" onclick="toggleChart('bb')">Bollinger</button><button id="superBtn" onclick="toggleChart('super')">SuperTrend</button><button id="ichBtn" onclick="toggleChart('ich')">Ichimoku</button><button id="srBtn" class="on" onclick="toggleChart('sr')">Destek/Direnç</button><button id="rsiBtn" class="on" onclick="toggleChart('rsi')">RSI</button><button id="macdBtn" onclick="toggleChart('macd')">MACD</button><button id="adxBtn" onclick="toggleChart('adx')">ADX</button><button id="volBtn" class="on" onclick="toggleChart('vol')">Hacim</button><button id="drawHBtn" class="ghost" onclick="setDrawMode('horizontal')">↔ Yatay</button><button id="drawTBtn" class="ghost" onclick="setDrawMode('trend')">╱ Trend</button><button id="drawFBtn" class="ghost" onclick="setDrawMode('fib')">Fibonacci</button><button class="ghost" onclick="clearDrawings()">Çizimleri Temizle</button><button class="ghost" onclick="resetChartView()">Sıfırla</button></div><div class="chartbox"><canvas id="priceChart" class="chartcanvas"></canvas><div id="chartTooltip" class="note" style="display:none;position:absolute;right:12px;top:12px;z-index:2;min-width:210px"></div><div class="chartlegend"><span>🕯 Mum</span><span>EMA20</span><span>EMA50</span><span>EMA200</span><span>RSI</span><span>MACD</span><span>ADX</span><span>SuperTrend</span><span>Ichimoku</span></div></div></div><div class="two" style="margin-top:14px"><div class="card"><h3>🧠 FurkAI Score Neden ${fmt(d.score)}/100?</h3>${bd}<div class="note" style="margin-top:12px">${esc(d.score_note||'Teknik sinyal gücü; kâr olasılığı değildir.')}</div></div><div class="card"><h3>Koşullar & Modeller</h3><div class="checklist">${checks}</div><h3 style="margin-top:18px">Aktif modeller</h3><div>${models||'<span class="muted">Aktif model yok.</span>'}</div><div style="margin-top:14px"><button class="ghost" onclick="$('kapSym').value=decodeURIComponent('${encodeURIComponent(clean)}');go('kap');loadKAP()">📢 KAP</button> <button class="primary" onclick="aiStock()">🤖 AI Kararını Oluştur</button></div></div></div>`;window.currentChartData=hist;window.currentChartInterval='1d';startChartLiveRefresh();window.currentChartState={ema20:true,ema50:true,ema200:false,bb:false,super:false,ich:false,sr:true,rsi:true,macd:false,adx:false,vol:true,start:0,end:hist.close.length,crossIndex:null};drawFurkChart(hist,d);attachChartInteractions()}catch(e){$('analysisOut').innerHTML='<div class="note">'+esc(e.message)+'</div>'}}

async function setChartInterval(interval){try{const sym=$('sym').value.trim().toUpperCase(),range=$('analysisRange').value;const hist=(await get('/api/history?symbol='+encodeURIComponent(sym)+'&range='+range+'&interval='+interval)).data;window.currentChartData=hist;window.currentChartInterval=interval;window.currentChartState.start=0;window.currentChartState.end=hist.close.length;window.currentChartState.crossIndex=null;['1d','1h','4h','1w','15m','1mo'].forEach(x=>{const b=$('tf'+x);if(b)b.classList.toggle('on',x===interval)});drawFurkChart(hist,window.currentAnalysis||{});}
catch(e){const tip=$('chartTooltip');if(tip){tip.style.display='block';tip.textContent=e.message}}}

function toggleChart(key){const st=window.currentChartState;if(!st)return;st[key]=!st[key];const b=$(key==='super'?'superBtn':key==='ich'?'ichBtn':key==='sr'?'srBtn':key+'Btn');if(b)b.classList.toggle('on',!!st[key]);drawFurkChart(window.currentChartData,window.currentAnalysis||{})}
function emaArr(a,n){let out=[],k=2/(n+1),prev=null;for(const x of a){prev=prev==null?x:x*k+prev*(1-k);out.push(prev)}return out}
function smaArr(a,n){return a.map((_,i)=>i+1<n?null:a.slice(i+1-n,i+1).reduce((x,y)=>x+y,0)/n)}
function stdArr(a,n){return a.map((_,i)=>{if(i+1<n)return null;const m=smaArr(a,n)[i],w=a.slice(i+1-n,i+1);return Math.sqrt(w.reduce((q,z)=>q+(z-m)**2,0)/n)})}
function rsiArr(a,n=14){let out=Array(a.length).fill(null),g=0,l=0;if(a.length<=n)return out;for(let i=1;i<=n;i++){const ch=a[i]-a[i-1];g+=Math.max(ch,0);l+=Math.max(-ch,0)}let ag=g/n,al=l/n;out[n]=al===0?100:100-100/(1+ag/al);for(let i=n+1;i<a.length;i++){const ch=a[i]-a[i-1];ag=(ag*(n-1)+Math.max(ch,0))/n;al=(al*(n-1)+Math.max(-ch,0))/n;out[i]=al===0?100:100-100/(1+ag/al)}return out}
function macdArr(a){const e12=emaArr(a,12),e26=emaArr(a,26),m=a.map((_,i)=>e12[i]-e26[i]),sig=emaArr(m,9);return {m,sig,h:m.map((v,i)=>v-sig[i])}}
function atrArr(h,n=14){const tr=h.high.map((v,i)=>i===0?v-h.low[i]:Math.max(v-h.low[i],Math.abs(v-h.close[i-1]),Math.abs(h.low[i]-h.close[i-1])));return emaArr(tr,n)}
function supertrendArr(h,n=10,mult=3){const atr=atrArr(h,n),up=[],dn=[],st=[];for(let i=0;i<h.close.length;i++){const mid=(h.high[i]+h.low[i])/2;up[i]=mid+mult*atr[i];dn[i]=mid-mult*atr[i];if(i===0)st[i]=dn[i];else st[i]=h.close[i]>st[i-1]?Math.max(dn[i],st[i-1]):Math.min(up[i],st[i-1]);}return st}
function adxArr(h,n=14){const tr=[],pdm=[],mdm=[];for(let i=0;i<h.close.length;i++){if(i===0){tr.push(h.high[i]-h.low[i]);pdm.push(0);mdm.push(0);continue}const up=h.high[i]-h.high[i-1],down=h.low[i-1]-h.low[i];pdm.push(up>down&&up>0?up:0);mdm.push(down>up&&down>0?down:0);tr.push(Math.max(h.high[i]-h.low[i],Math.abs(h.high[i]-h.close[i-1]),Math.abs(h.low[i]-h.close[i-1])))}const atr=emaArr(tr,n),p=emaArr(pdm,n),m=emaArr(mdm,n),dx=[];for(let i=0;i<h.close.length;i++){const pi=atr[i]?100*p[i]/atr[i]:0,mi=atr[i]?100*m[i]/atr[i]:0;dx.push((pi+mi)?100*Math.abs(pi-mi)/(pi+mi):0)}return emaArr(dx,n)}
function ichimokuArr(h){const n=h.close.length,ten=[],kij=[],sa=[],sb=[];const mid=(i,p)=>{if(i+1<p)return null;let hi=-Infinity,lo=Infinity;for(let j=i-p+1;j<=i;j++){hi=Math.max(hi,h.high[j]);lo=Math.min(lo,h.low[j])}return (hi+lo)/2};for(let i=0;i<n;i++){ten[i]=mid(i,9);kij[i]=mid(i,26);sa[i]=ten[i]!=null&&kij[i]!=null?(ten[i]+kij[i])/2:null;sb[i]=mid(i,52)}return {ten,kij,sa,sb}}
function fmtDate(ts){if(!ts)return '';const d=new Date(ts*1000);return d.toLocaleString('tr-TR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}
function drawFurkChart(h,d){const c=$('priceChart');if(!c||!h)return;const rect=c.getBoundingClientRect(),ratio=devicePixelRatio||1;c.width=Math.max(700,rect.width)*ratio;c.height=500*ratio;const x=c.getContext('2d');x.setTransform(ratio,0,0,ratio,0,0);const w=Math.max(700,rect.width),H=500;x.clearRect(0,0,w,H);x.fillStyle='#07111f';x.fillRect(0,0,w,H);const n=(h.close||[]).length;if(!n)return;const st=window.currentChartState||{},start=Math.max(0,Math.min(n-50,st.start||0)),end=Math.min(n,Math.max(start+50,st.end||n)),viewN=end-start;const pad={l:52,r:70,t:18,b:22},plotW=w-pad.l-pad.r;const volH=st.vol?55:0,indH=(st.rsi?65:0)+(st.macd?75:0)+(st.adx?65:0),priceH=H-pad.t-pad.b-volH-indH;const step=plotW/Math.max(1,viewN-1),body=Math.max(2,step*.58),xs=i=>pad.l+(i-start)*(plotW/Math.max(1,viewN-1));const highs=h.high,lows=h.low,closes=h.close,opens=h.open,vols=h.volume;const all=highs.slice(start,end).concat(lows.slice(start,end)).filter(Number.isFinite),pmin=Math.min(...all),pmax=Math.max(...all),pr=pmax-pmin||1,py=v=>pad.t+(pmax-v)/pr*(priceH-22);x.strokeStyle='#1d304b';x.lineWidth=1;for(let j=0;j<5;j++){const yy=pad.t+j*(priceH-22)/4;x.beginPath();x.moveTo(pad.l,yy);x.lineTo(w-pad.r,yy);x.stroke();x.fillStyle='#71839b';x.font='11px Arial';x.fillText((pmax-pr*j/4).toFixed(2),w-pad.r+8,yy+4)}for(let i=start;i<end;i++){const xx=xs(i),yo=py(opens[i]),yc=py(closes[i]),yh=py(highs[i]),yl=py(lows[i]),up=closes[i]>=opens[i];x.strokeStyle=up?'#39d39b':'#ff6878';x.fillStyle=up?'#39d39b':'#ff6878';x.beginPath();x.moveTo(xx,yh);x.lineTo(xx,yl);x.stroke();x.fillRect(xx-body/2,Math.min(yo,yc),body,Math.max(1,Math.abs(yc-yo)))}
const drawLine=(arr,col,width=1.6)=>{x.strokeStyle=col;x.lineWidth=width;x.beginPath();let first=true;for(let i=start;i<end;i++){const v=arr[i];if(v==null||!Number.isFinite(v))continue;const xx=xs(i),yy=py(v);if(first){x.moveTo(xx,yy);first=false}else x.lineTo(xx,yy)}x.stroke()};if(st.ema20)drawLine(emaArr(closes,20),'#36d7a0');if(st.ema50)drawLine(emaArr(closes,50),'#5c8dff');if(st.ema200)drawLine(emaArr(closes,200),'#c18cff');if(st.bb){const mid=smaArr(closes,20),sd=stdArr(closes,20);drawLine(mid.map((v,i)=>v==null?null:v+2*sd[i]),'#f3c75b');drawLine(mid.map((v,i)=>v==null?null:v-2*sd[i]),'#f3c75b');drawLine(mid,'#d9b85b',1)}if(st.super)drawLine(supertrendArr(h,10,3),'#ff9f43',2);if(st.ich){const ic=ichimokuArr(h);drawLine(ic.ten,'#43c8e8');drawLine(ic.kij,'#ff7eb6');drawLine(ic.sa,'#9b7cff');drawLine(ic.sb,'#6dd5a7')}
if(st.sr){const recent=closes.slice(Math.max(0,n-60));const hi=Math.max(...recent),lo=Math.min(...recent);[hi,lo].forEach((v,idx)=>{const yy=py(v);x.strokeStyle=idx===0?'#ff6878':'#39d39b';x.setLineDash([6,5]);x.beginPath();x.moveTo(pad.l,yy);x.lineTo(w-pad.r,yy);x.stroke();x.setLineDash([]);x.fillStyle=idx===0?'#ff6878':'#39d39b';x.fillText(idx===0?'Direnç':'Destek',pad.l+5,yy-5)})}
// FurkAI historical signal markers derived from current analysis checks/model state.
const sig=d?.signal||'BEKLE';if(sig!=='BEKLE'){const idx=end-1,yy=py(closes[idx]);x.fillStyle=sig==='AL'?'#39d39b':sig==='SAT'?'#ff6878':'#f3c75b';x.beginPath();x.arc(xs(idx),yy,6,0,Math.PI*2);x.fill();x.fillStyle='#fff';x.font='bold 11px Arial';x.fillText('FurkAI '+sig,xs(idx)+9,yy-8)}
let y=pad.t+priceH;const rr=rsiArr(closes);if(st.rsi){x.strokeStyle='#293d59';x.beginPath();x.moveTo(pad.l,y);x.lineTo(w-pad.r,y);x.stroke();const ry=y+10,rpy=v=>ry+42-v/100*42;drawIndicatorLine(rr,rpy,xs,x,start,end,'#9b7cff');x.fillStyle='#71839b';x.fillText('RSI 70/30',pad.l,ry+55);y+=65}const mac=macdArr(closes);if(st.macd){const base=y+35;x.strokeStyle='#293d59';x.beginPath();x.moveTo(pad.l,base);x.lineTo(w-pad.r,base);x.stroke();const vals=mac.m.slice(start,end).concat(mac.sig.slice(start,end)).filter(Number.isFinite),mi=Math.min(...vals),ma=Math.max(...vals),mr=ma-mi||1;const mp=v=>y+5+(ma-v)/mr*60;drawIndicatorLine(mac.m,mp,xs,x,start,end,'#43c8e8');drawIndicatorLine(mac.sig,mp,xs,x,start,end,'#f3c75b');x.fillStyle='#71839b';x.fillText('MACD',pad.l,y+72);y+=75}if(st.adx){const aa=adxArr(h),base=y+10;const ar=v=>base+45-v/60*45;x.strokeStyle='#293d59';x.beginPath();x.moveTo(pad.l,base+45);x.lineTo(w-pad.r,base+45);x.stroke();drawIndicatorLine(aa,ar,xs,x,start,end,'#ff9f43');x.fillStyle='#71839b';x.fillText('ADX',pad.l,base+58)}if(st.vol){const vy=H-55,vm=Math.max(...vols.slice(start,end),1);for(let i=start;i<end;i++){x.fillStyle='#27496d';const hh=(vols[i]/vm)*45;x.fillRect(xs(i)-Math.max(1,step*.3),vy-hh,Math.max(1,step*.6),hh)}x.fillStyle='#71839b';x.fillText('Hacim',pad.l,H-5)}if(st.crossIndex!=null&&st.crossIndex>=start&&st.crossIndex<end){const cx=xs(st.crossIndex);x.strokeStyle='#8fa0b8';x.setLineDash([4,4]);x.beginPath();x.moveTo(cx,pad.t);x.lineTo(cx,H-10);x.stroke();x.setLineDash([]);const tip=$('chartTooltip');if(tip){tip.style.display='block';tip.innerHTML=`<b>${fmtDate(h.timestamp?.[st.crossIndex])}</b><br>Açılış: ${fmt(opens[st.crossIndex])}<br>Yüksek: ${fmt(highs[st.crossIndex])}<br>Düşük: ${fmt(lows[st.crossIndex])}<br>Kapanış: <b>${fmt(closes[st.crossIndex])}</b>`}}drawChartOverlays(x,w,H,pad,start,end,st);}
function drawIndicatorLine(arr,mapper,xs,x,start,end,col){x.strokeStyle=col;x.lineWidth=1.5;x.beginPath();let first=true;for(let i=start;i<end;i++){const v=arr[i];if(v==null||!Number.isFinite(v))continue;const xx=xs(i),yy=mapper(v);if(first){x.moveTo(xx,yy);first=false}else x.lineTo(xx,yy)}x.stroke()}
let chartDrawMode=null;
function setDrawMode(mode){chartDrawMode=mode;document.querySelectorAll('#drawHBtn,#drawTBtn,#drawFBtn').forEach(b=>b.classList.remove('on'));const id=mode==='horizontal'?'drawHBtn':mode==='trend'?'drawTBtn':'drawFBtn';if($(id))$(id).classList.add('on');const c=$('priceChart');if(c)c.style.cursor='crosshair';}
function clearDrawings(){window.chartDrawings=[];drawFurkChart(window.currentChartData,window.currentAnalysis||{});}
function drawChartOverlays(ctx,w,H,pad,start,end,st){const ds=window.chartDrawings||[];for(const d of ds){ctx.strokeStyle=d.type==='fib'?'#f3c75b':'#8ea8ff';ctx.lineWidth=1.4;ctx.setLineDash(d.type==='horizontal'?[6,5]:[]);if(d.type==='horizontal'){ctx.beginPath();ctx.moveTo(pad.l,d.y);ctx.lineTo(w-pad.r,d.y);ctx.stroke();}else{ctx.setLineDash([]);ctx.beginPath();ctx.moveTo(d.x1,d.y1);ctx.lineTo(d.x2,d.y2);ctx.stroke();if(d.type==='fib'){for(const r of [0,0.236,0.382,0.5,0.618,0.786,1]){const y=d.y1+(d.y2-d.y1)*r;ctx.fillText((r*100).toFixed(1)+'%',d.x2+4,y);ctx.beginPath();ctx.moveTo(d.x1,y);ctx.lineTo(d.x2,y);ctx.stroke();}}}}ctx.setLineDash([]);}
let chartLiveTimer=null;
function startChartLiveRefresh(){if(chartLiveTimer)clearInterval(chartLiveTimer);try{const enabled=STORE.get('furkai_auto_refresh','true')!=='false';if(!enabled)return;const sec=Math.max(5,Number(STORE.get('furkai_refresh_seconds','15')||15));chartLiveTimer=setInterval(async()=>{if(page!=='analysis')return;try{const sym=$('sym').value.trim().toUpperCase();const h=(await get('/api/history?symbol='+encodeURIComponent(sym)+'&range='+$('analysisRange').value+'&interval='+window.currentChartInterval)).data;window.currentChartData=h;window.currentChartState.start=Math.max(0,h.close.length-(window.currentChartState.end-window.currentChartState.start));window.currentChartState.end=h.close.length;drawFurkChart(h,window.currentAnalysis||{});}catch(e){}} ,sec*1000);}catch(e){}}
function resetChartView(){if(window.currentChartData){window.currentChartState.start=0;window.currentChartState.end=window.currentChartData.close.length;window.currentChartState.crossIndex=null;drawFurkChart(window.currentChartData,window.currentAnalysis||{});}}
function attachChartInteractions(){const c=$('priceChart');if(!c||c.dataset.bound==='1')return;c.dataset.bound='1';let drag=false,lastX=0;c.style.cursor='crosshair';c.addEventListener('wheel',e=>{e.preventDefault();const st=window.currentChartState,h=window.currentChartData,n=h?.close?.length||0;if(!n)return;const span=st.end-st.start;const next=Math.max(50,Math.min(n,Math.round(span*(e.deltaY<0?.82:1.22))));const ratio=Math.max(0,Math.min(1,(e.offsetX||c.clientWidth/2)/c.clientWidth));const center=st.start+span*ratio;st.start=Math.max(0,Math.min(n-next,Math.round(center-next*ratio)));st.end=st.start+next;drawFurkChart(h,window.currentAnalysis||{});},{passive:false});c.addEventListener('mousedown',e=>{drag=true;lastX=e.clientX;c.style.cursor='grabbing'});window.addEventListener('mouseup',()=>{drag=false;const el=$('priceChart');if(el)el.style.cursor='crosshair'});c.addEventListener('mousemove',e=>{const st=window.currentChartState,h=window.currentChartData,n=h?.close?.length||0;if(!n)return;const rect=c.getBoundingClientRect();st.crossIndex=Math.max(st.start,Math.min(st.end-1,Math.round(st.start+((e.clientX-rect.left)/rect.width)*(st.end-st.start))));if(drag){const span=st.end-st.start,dx=e.clientX-lastX;lastX=e.clientX;const shift=Math.round(-dx/rect.width*span);st.start=Math.max(0,Math.min(n-span,st.start+shift));st.end=st.start+span;}drawFurkChart(h,window.currentAnalysis||{});});c.addEventListener('mouseleave',()=>{const t=$('chartTooltip');if(t)t.style.display='none'});c.addEventListener('click',e=>{if(!chartDrawMode)return;const rect=c.getBoundingClientRect();const x=e.clientX-rect.left,y=e.clientY-rect.top;window.chartDrawings=window.chartDrawings||[];if(chartDrawMode==='horizontal')window.chartDrawings.push({type:'horizontal',y});else if(chartDrawMode==='trend')window.chartDrawings.push({type:'trend',x1:x,y1:y,x2:Math.min(rect.width-20,x+140),y2:y-60});else window.chartDrawings.push({type:'fib',x1:Math.max(50,x-120),y1:y+80,x2:Math.min(rect.width-70,x+120),y2:y-80});drawFurkChart(window.currentChartData,window.currentAnalysis||{});});}

