async function addPosition(){
  const symbol=$('pSym').value.trim().toUpperCase().replace('.IS','');
  const qty=Number($('pQty').value);
  const cost=Number($('pCost').value);
  const label=$('pLabel').value.trim();
  if(!symbol||!Number.isFinite(qty)||qty<=0||!Number.isFinite(cost)||cost<=0){
    showToast('Hisse, adet ve maliyet bilgilerini doğru gir.','bad'); return;
  }
  try{
    const d=await get('/api/portfolio');
    const rows=Array.isArray(d.portfolio)?d.portfolio:[];
    const cleanSymbol=symbol+'.IS';
    const existing=rows.find(x=>String(x.symbol).toUpperCase()===cleanSymbol);
    if(existing){
      const totalQty=Number(existing.qty||0)+qty;
      existing.cost=((Number(existing.qty||0)*Number(existing.cost||0))+(qty*cost))/totalQty;
      existing.qty=totalQty;
      if(label)existing.label=label;
    }else{
      rows.push({id:Date.now(),symbol:cleanSymbol,label,qty,cost,note:'Manuel olarak eklendi'});
    }
    await get('/api/portfolio/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({portfolio:rows})});
    $('pSym').value='';$('pQty').value='';$('pCost').value='';$('pLabel').value='';
    showToast(existing?'Pozisyon güncellendi.':'Pozisyon eklendi.','info');
    await loadPortfolio();
  }catch(e){showToast(e.message||'Pozisyon eklenemedi.','bad')}
}
async function removePosition(id){
  if(!confirm('Bu pozisyonu portföyden silmek istediğine emin misin?'))return;
  try{
    const d=await get('/api/portfolio');
    const rows=(d.portfolio||[]).filter(x=>Number(x.id)!==Number(id));
    await get('/api/portfolio/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({portfolio:rows})});
    await loadPortfolio();
    showToast('Pozisyon silindi.','info');
  }catch(e){showToast(e.message||'Pozisyon silinemedi.','bad')}
}

async function editPosition(id){
  try{
    const d=await get('/api/portfolio');
    const p=d.portfolio.find(x=>Number(x.id)===Number(id));
    if(!p)return;
    const qty=prompt('Adet',String(p.qty)); if(qty===null)return;
    const cost=prompt('Maliyet / adet',String(p.cost)); if(cost===null)return;
    const label=prompt('Açıklama',p.label||''); if(label===null)return;
    const q=Number(qty), c=Number(cost);
    if(!Number.isFinite(q)||q<=0||!Number.isFinite(c)||c<=0){showToast('Adet ve maliyet pozitif sayılar olmalı.','bad');return;}
    p.qty=q; p.cost=c; p.label=label;
    await get('/api/portfolio/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({portfolio:d.portfolio})});
    await loadPortfolio(); showToast('Pozisyon güncellendi.','info');
  }catch(e){showToast(e.message||'Pozisyon güncellenemedi.','bad')}
}
function openStock(encoded){
  const sym=decodeURIComponent(String(encoded||'')).replace('.IS','').toUpperCase();
  if(!sym)return;
  $('sym').value=sym;
  go('analysis');
  analyzeStock();
}
async function loadPortfolio(){
  const d=await get('/api/portfolio');
  const rows=Array.isArray(d.portfolio)?d.portfolio:[];
  if(!rows.length){$('portTable').innerHTML='<div class="empty">Portföy boş. Yukarıdaki formdan ilk pozisyonunu ekleyebilirsin.</div>';return}
  let quotes={};let quoteError='';
  try{const qs=await get('/api/quotes?symbols='+encodeURIComponent(rows.map(x=>x.symbol).join(',')));quotes=qs.quotes||{}}catch(e){quoteError=e.message||'Güncel fiyat verisi alınamadı.'}
  const totalCost=rows.reduce((a,x)=>a+Number(x.qty||0)*Number(x.cost||0),0);
  const totalValue=rows.reduce((a,x)=>{const q=quotes?.[x.symbol]?.price;return a+(q==null?0:Number(x.qty||0)*Number(q))},0);
  const liveCount=rows.filter(x=>quotes?.[x.symbol]?.price!=null).length;
  $('portTable').innerHTML=`<div class="grid3" style="margin-bottom:14px"><div class="card kpi-accent"><div class="muted">Toplam Değer</div><div class="metric">${liveCount?fmt(totalValue)+' ₺':'—'}</div></div><div class="card kpi-blue"><div class="muted">Toplam Maliyet</div><div class="metric">${fmt(totalCost)} ₺</div></div><div class="card kpi-warn"><div class="muted">Toplam K/Z</div><div class="metric">${liveCount?fmt(totalValue-totalCost)+' ₺':'—'}</div></div></div>${quoteError?'<div class="note">⚠️ Kayıtlı portföy gösteriliyor. Güncel fiyat servisine şu anda ulaşılamıyor; fiyat/KZ alanları veri geldiğinde hesaplanacak.</div>':''}<table class="table"><thead><tr><th>Hisse</th><th>Adet</th><th>Maliyet / Adet</th><th>Güncel</th><th>K/Z</th><th>Ağırlık</th><th>Aksiyon</th><th></th></tr></thead><tbody>`+rows.map(x=>{const price=quotes?.[x.symbol]?.price??null;const pnl=price==null?null:(price-x.cost)*x.qty;const weight=totalValue>0&&price!=null?(x.qty*price/totalValue)*100:null;const sym=String(x.symbol).replace('.IS','');return `<tr><td><b style="cursor:pointer" onclick="openStock(encodeURIComponent('${sym}'))">${esc(x.symbol)}</b><br><span class="muted">${esc(x.label||'')}</span></td><td>${fmt(x.qty)}</td><td>${fmt(x.cost)}</td><td>${price==null?'—':fmt(price)}</td><td class="${pnl==null?'muted':pnl>=0?'good':'bad'}">${pnl==null?'—':fmt(pnl)+' ₺'}</td><td>${weight==null?'—':fmt(weight)+'%'}</td><td><button class="ghost" onclick="openStock(encodeURIComponent('${sym}'))">Analiz et →</button></td><td><button class="ghost" onclick="editPosition(${Number(x.id)})">Düzenle</button> <button class="danger" onclick="removePosition(${Number(x.id)})">Sil</button></td></tr>`}).join('')+'</tbody></table>';
}
async function loadSettings(){try{const d=await get('/api/config');const admin=!!d.is_admin;if($('setGeminiKey')&&$('setGeminiKey').closest('label'))$('setGeminiKey').closest('label').style.display=admin?'block':'none';document.querySelectorAll('#settings button').forEach(b=>{if(/Ayarları Kaydet/.test(b.textContent))b.style.display=admin?'inline-flex':'none'});if($('settingsStatus')&&!admin)$('settingsStatus').dataset.roleNote='Kişisel giriş / tema ayarları yerelde tutulur; paylaşılan uygulama ayarlarını yalnızca yönetici değiştirir.';$('setGeminiKey').placeholder=d.gemini_key_masked||'AIza...';$('setGeminiKey').value='';$('setGeminiModel').value=d.gemini_model||'gemini-3.6-flash';$('setScannerLimit').value=d.scanner_limit||250;$('setPeriod').value=d.default_period||'1y';$('setInterval').value=d.default_interval||'1d';$('setRefresh').value=d.refresh_seconds||15;$('setAutoRefresh').checked=!!d.auto_refresh;STORE.set('furkai_refresh_seconds',d.refresh_seconds||15);STORE.set('furkai_auto_refresh',String(!!d.auto_refresh));if($('setTheme'))$('setTheme').value=d.theme||STORE.get('furkai_theme','dark');$('settingsStatus').innerHTML=d.gemini_configured?'<span class="good">✓ Gemini anahtarı yapılandırılmış.</span>':'<span class="warn">Gemini anahtarı henüz yapılandırılmamış.</span>'}catch(e){$('settingsStatus').textContent=e.message}}async function saveSettings(){try{if((window.currentUser||{}).is_admin!==true){showToast('Paylaşılan ayarları yalnızca yönetici değiştirebilir.','bad');return}const payload={gemini_model:$('setGeminiModel').value.trim(),scanner_limit:Number($('setScannerLimit').value),default_period:$('setPeriod').value,default_interval:$('setInterval').value,refresh_seconds:Number($('setRefresh').value),auto_refresh:$('setAutoRefresh').checked,theme:$('setTheme').value};const key=$('setGeminiKey').value.trim();if(key)payload.gemini_key=key;const d=await get('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});STORE.set('furkai_refresh_seconds',String(payload.refresh_seconds));STORE.set('furkai_auto_refresh',String(payload.auto_refresh));$('settingsStatus').innerHTML='<span class="good">✓ Ayarlar kaydedildi. '+(d.gemini_configured?'Gemini aktif.':'Gemini anahtarı yok.')+'</span>';loadDataStatus();startChartLiveRefresh()}catch(e){$('settingsStatus').innerHTML='<span class="bad">'+esc(e.message)+'</span>'}}async function testGemini(){try{const d=await get('/api/gemini-test',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('settingsStatus').innerHTML=d.ok?'<span class="good">✓ Gemini bağlantısı başarılı.</span>':'<span class="bad">✕ Gemini testi başarısız: '+esc(d.error||'Bilinmeyen hata')+'</span>'}catch(e){$('settingsStatus').innerHTML='<span class="bad">'+esc(e.message)+'</span>'}}async function loadDataStatus(){try{const d=await get('/api/data-status');$('dataYahoo').textContent=d.yahoo||'—';$('dataYahoo').className=d.yahoo==='OK'?'good':d.yahoo==='ERROR'?'bad':'warn';$('dataGemini').textContent=d.gemini||'—';$('dataGemini').className=d.gemini==='CONFIGURED'?'good':'warn';$('dataCache').textContent=fmt(d.last_cache_items||0);$('dataFreshness').textContent=d.freshness||'UNKNOWN';$('dataFreshness').className=d.freshness==='FRESH'?'good':d.freshness==='STALE'?'warn':'bad';$('dataLast').textContent=d.last_timestamp?new Date(Number(d.last_timestamp)*1000).toLocaleString('tr-TR'):'—';$('dataVersion').textContent=d.app_version||'V15.9.6'}catch(e){$('dataYahoo').textContent='HATA';$('dataYahoo').className='bad'}}
const STORE={get(k,f=null){try{return localStorage.getItem(k)??f}catch(_){return f}},set(k,v){try{localStorage.setItem(k,v)}catch(_){}},remove(k){try{localStorage.removeItem(k)}catch(_){} }};
function setTheme(mode){mode=['dark','light','system'].includes(mode)?mode:'dark';STORE.set('furkai_theme',mode);const effective=mode==='system'?(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):mode;applyTheme(effective);if($('setTheme'))$('setTheme').value=mode;document.querySelectorAll('.theme-switch button').forEach(b=>b.classList.toggle('active',(mode==='dark'&&b.id==='themeDark')||(mode==='light'&&b.id==='themeLight')||(mode==='system'&&b.id==='themeSystem')))}
function applyTheme(mode){document.body.classList.toggle('theme-light',mode==='light');document.documentElement.style.colorScheme=mode==='light'?'light':'dark'}
function initTheme(){const saved=STORE.get('furkai_theme','dark');setTheme(saved)}
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(STORE.get('furkai_theme','dark')==='system')initTheme()});
window.addEventListener('error',e=>{console.error(e.error||e.message);showToast('Arayüz hatası: '+(e.message||'Bilinmeyen JavaScript hatası'),'bad')});
window.addEventListener('unhandledrejection',e=>{console.error(e.reason);showToast('İşlem hatası: '+(e.reason?.message||e.reason||'Bilinmeyen hata'),'bad')});
renderModels();try{initTheme()}catch(e){console.error(e);applyTheme('dark')}go('dashboard');
function renderAIPanel(targetId,sym,d,obj){const panel=$(targetId);if(!panel)return;panel.style.display='block';const decision=obj?.decision||'NÖTR';const confidence=obj?.confidence;panel.innerHTML=`<div class="ai-panel-head"><div><div class="ai-source">FURKAI · GEMINI KARAR DESTEĞİ</div><h3>🤖 ${esc(sym)} · ${esc(decision)}</h3></div><div class="scan-actions">${confidence!=null?`<span class="pill">Güven ${esc(confidence)}/100</span>`:''}<button class="ghost" onclick="closeAIPanel('${targetId}')">Kapat</button></div></div><div class="ai-panel-body">${obj?`<div class="ai-grid"><div class="ai-box">Karar<b>${esc(decision)}</b></div><div class="ai-box">Giriş<b>${obj.suggested_entry==null?'—':esc(obj.suggested_entry)}</b></div><div class="ai-box">Stop<b>${obj.stop==null?'—':esc(obj.stop)}</b></div><div class="ai-box">Hedef<b>${obj.target==null?'—':esc(obj.target)}</b></div></div><div class="ai-factors"><div class="note"><b>Destekleyen faktörler</b><br>${(obj.reasons||[]).map(x=>'• '+esc(x)).join('<br>')||'—'}</div><div class="note"><b>Riskler / geçersizleşme</b><br>${(obj.risks||[]).map(x=>'• '+esc(x)).join('<br>')||'—'}<br><br><b>Geçersizleşme:</b> ${esc(obj.invalidate_reason||'—')}</div></div>`:`<pre style="white-space:pre-wrap;color:var(--text);line-height:1.65;margin:0">${esc(d?.text||d?.error||'Yanıt yok')}</pre>`}</div>`}
function closeAIPanel(id){const p=$(id);if(p){p.style.display='none';p.innerHTML=''}}
async function aiStock(){const sym=$('sym').value.trim().toUpperCase();const panel=$('aiDecisionPanel');panel.style.display='block';panel.innerHTML='<div class="ai-panel-body"><div class="scan-loading"><i class="spinner"></i> Gemini teknik veriyi yorumluyor…</div></div>';try{const d=await get('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({symbol:sym})});let obj=null;try{obj=JSON.parse(String(d.text||'').replace(/```json|```/g,'').trim())}catch(e){}renderAIPanel('aiDecisionPanel',sym,d,obj)}catch(e){renderAIPanel('aiDecisionPanel',sym,{error:e.message},null)}}
