async function loadPortfolioIntel(){try{const d=await get('/api/portfolio/intelligence');const rows=d.positions||[];const div=d.diversification_score==null?'—':fmt(d.diversification_score)+'/100';const divLabel=d.diversification_label||'BİLİNMİYOR';const corr=(d.correlations||[])[0];const riskSummary=`<div class="ai-grid" style="margin-bottom:12px"><div class="ai-box"><span class="muted">Çeşitlendirme</span><b>${div}</b></div><div class="ai-box"><span class="muted">Durum</span><b>${esc(divLabel)}</b></div><div class="ai-box"><span class="muted">En yüksek korelasyon</span><b>${corr?esc(String(corr.a).replace('.IS','')+' ↔ '+String(corr.b).replace('.IS','')+' · '+fmt(corr.corr)): '—'}</b></div></div>`;$('portIntel').innerHTML=rows.length?riskSummary+`<table class="table intel-table"><thead><tr><th>Hisse</th><th>Score</th><th>Trend</th><th>RSI</th><th>Momentum</th><th>Ağırlık</th><th>Risk</th><th>Risk Faktörleri</th><th>Aksiyon</th></tr></thead><tbody>${rows.map(x=>{const rc=x.risk==='YÜKSEK'?'risk-high':x.risk==='ORTA'?'risk-mid':'risk-low';const ac=x.action.includes('TUT')?'action-buy':x.action.includes('RİSK')?'action-risk':'action-watch';return `<tr><td><b>${esc(String(x.symbol).replace('.IS',''))}</b></td><td><span class="pill">${x.score==null?'—':fmt(x.score)+'/100'}</span></td><td>${esc(x.trend||'—')}</td><td>${fmt(x.rsi)}</td><td>${fmt(x.momentum)}%</td><td>${fmt(x.weight)}%</td><td class="${rc}">${esc(x.risk||'—')}</td><td>${esc((x.risk_factors||[]).join(' · ')||'—')}</td><td class="${ac}">${esc(x.action||'—')}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">Portföy boş.</div>'}catch(e){$('portIntel').innerHTML='<div class="note">'+esc(e.message)+'</div>'}}
